import random
rnd = random.Random(1)
ts = sol.TaskScheduler()
N = 50000
for i in range(N):
    ts.submit(i, rnd.randrange(1000000))
acc = 0
for i in range(50000):
    r = rnd.random()
    t = rnd.randrange(N)
    if r < 0.3:
        try:
            ts.reprioritize(t, rnd.randrange(1000000))
        except KeyError:
            acc += 1
    elif r < 0.6:
        acc = (acc * 31 + ts.peek()) % 1000000007
    else:
        acc = (acc * 31 + ts.pop()) % 1000000007
result = [acc, len(ts)]

